import heapq
class Solution:
    def minCost(self, m: int, n: int, penalty: List[List[int]]) -> int:
        INF = float('inf')
        dist = [[INF, INF] for _ in range(m * n)]
        start = 1  # state (0,0), next action odd
        dist[0][1] = 1
        pq = [(1, 0, 0, 1)]
        while pq:
            d, i, j, p = heapq.heappop(pq)
            if d > dist[i * n + j][p]:
                continue
            if i == m - 1 and j == n - 1:
                return d
            np = 1 - p
            # wait
            w = d + penalty[i][j]
            if w < dist[i * n + j][np]:
                dist[i * n + j][np] = w
                heapq.heappush(pq, (w, i, j, np))
            dirs = [(0,1),(1,0)] if p == 1 else [(0,-1),(-1,0)]
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n:
                    c = d + (ni + 1) * (nj + 1) + (0 if p == 1 else penalty[i][j])
                    if c < dist[ni * n + nj][np]:
                        dist[ni * n + nj][np] = c
                        heapq.heappush(pq, (c, ni, nj, np))
        return -1

