var minCost = function(m, n, penalty) {
    const INF = Infinity;
    const dist = Array.from({length: m * n}, () => [INF, INF]);
    dist[0][1] = 1;
    const pq = [[1, 0, 0, 1]];
    const push = (x) => {
        pq.push(x);
        let i = pq.length - 1;
        while (i > 0) {
            const par = (i - 1) >> 1;
            if (pq[par][0] <= pq[i][0]) break;
            [pq[par], pq[i]] = [pq[i], pq[par]];
            i = par;
        }
    };
    const pop = () => {
        const top = pq[0], last = pq.pop();
        if (pq.length) {
            pq[0] = last;
            let i = 0;
            for (;;) {
                let l = 2*i+1, r = 2*i+2, s = i;
                if (l < pq.length && pq[l][0] < pq[s][0]) s = l;
                if (r < pq.length && pq[r][0] < pq[s][0]) s = r;
                if (s === i) break;
                [pq[s], pq[i]] = [pq[i], pq[s]];
                i = s;
            }
        }
        return top;
    };
    while (pq.length) {
        const [d, i, j, p] = pop();
        if (d > dist[i * n + j][p]) continue;
        if (i === m - 1 && j === n - 1) return d;
        const np = 1 - p;
        const w = d + penalty[i][j];
        if (w < dist[i * n + j][np]) {
            dist[i * n + j][np] = w;
            push([w, i, j, np]);
        }
        const dirs = p === 1 ? [[0,1],[1,0]] : [[0,-1],[-1,0]];
        for (const [di, dj] of dirs) {
            const ni = i + di, nj = j + dj;
            if (ni < 0 || ni >= m || nj < 0 || nj >= n) continue;
            const c = d + (ni + 1) * (nj + 1) + (p === 1 ? 0 : penalty[i][j]);
            if (c < dist[ni * n + nj][np]) {
                dist[ni * n + nj][np] = c;
                push([c, ni, nj, np]);
            }
        }
    }
    return -1;
};

