from collections import deque
class Solution:
    def minCost(self, m: int, n: int, penalty: List[List[int]]) -> int:
        INF = float('inf')
        dist = [[INF, INF] for _ in range(m * n)]
        dist[0][1] = 1
        inq = [[False, False] for _ in range(m * n)]
        dq = deque([(0, 0, 1)])
        inq[0][1] = True
        while dq:
            i, j, p = dq.popleft()
            inq[i * n + j][p] = False
            d = dist[i * n + j][p]
            np = 1 - p
            cand = [(i, j, d + penalty[i][j])]
            dirs = [(0,1),(1,0)] if p == 1 else [(0,-1),(-1,0)]
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n:
                    cand.append((ni, nj, d + (ni + 1) * (nj + 1) + (0 if p == 1 else penalty[i][j])))
            for ni, nj, c in cand:
                if c < dist[ni * n + nj][np]:
                    dist[ni * n + nj][np] = c
                    if not inq[ni * n + nj][np]:
                        inq[ni * n + nj][np] = True
                        dq.append((ni, nj, np))
        return int(min(dist[(m - 1) * n + (n - 1)]))

