                if (ni < 0 || ni >= m || nj < 0 || nj >= n) continue;
                cand.push_back({(long long)ni, (long long)nj,
                                d + (long long)(ni + 1) * (nj + 1) + (p == 1 ? 0 : penalty[i][j])});
            }
            for (auto& c : cand) {
                int ni = (int)c[0], nj = (int)c[1];
                if (c[2] < dist[ni * n + nj][np]) {
                    dist[ni * n + nj][np] = c[2];
