                        inq[ni * n + nj][np] = true;
                        dq.push_back({ni, nj, np});
                    }
                }
            }
        }
        return (int)min(dist[(m - 1) * n + (n - 1)][0], dist[(m - 1) * n + (n - 1)][1]);
    }
