class Solution {
    public int minCost(int m, int n, int[][] penalty) {
        long INF = Long.MAX_VALUE;
        long[][] dist = new long[m * n][2];
        boolean[][] inq = new boolean[m * n][2];
        for (long[] row : dist) Arrays.fill(row, INF);
        dist[0][1] = 1;
        Deque<int[]> dq = new ArrayDeque<>();
        dq.offer(new int[]{0, 0, 1});
        inq[0][1] = true;
        int[][] dr = {{0,1},{1,0}}, dl = {{0,-1},{-1,0}};
        while (!dq.isEmpty()) {
            int[] cur = dq.poll();
            int i = cur[0], j = cur[1], p = cur[2];
            inq[i * n + j][p] = false;
            long d = dist[i * n + j][p];
            int np = 1 - p;
            relax(m, n, dist, inq, dq, i, j, d + penalty[i][j], np);
            for (int[] dd : (p == 1 ? dr : dl)) {
                int ni = i + dd[0], nj = j + dd[1];
                if (ni < 0 || ni >= m || nj < 0 || nj >= n) continue;
                relax(m, n, dist, inq, dq, ni, nj,
                      d + (long)(ni + 1) * (nj + 1) + (p == 1 ? 0 : penalty[i][j]), np);
            }
        }
        long a = dist[(m - 1) * n + (n - 1)][0], b = dist[(m - 1) * n + (n - 1)][1];
        return (int)Math.min(a, b);
    }
    private void relax(int m, int n, long[][] dist, boolean[][] inq, Deque<int[]> dq,
                       int i, int j, long c, int np) {
        if (c < dist[i * n + j][np]) {
            dist[i * n + j][np] = c;
            if (!inq[i * n + j][np]) {
                inq[i * n + j][np] = true;
                dq.offer(new int[]{i, j, np});
            }
        }
    }
}

