    const dist = Array.from({length: m * n}, () => [INF, INF]);
    const inq = Array.from({length: m * n}, () => [false, false]);
    dist[0][1] = 1;
    const dq = [[0, 0, 1]];
    inq[0][1] = true;
    while (dq.length) {
        const [i, j, p] = dq.shift();
        inq[i * n + j][p] = false;
        const d = dist[i * n + j][p];
        const np = 1 - p;
        const relax = (ni, nj, c) => {
            if (c < dist[ni * n + nj][np]) {
                dist[ni * n + nj][np] = c;
                if (!inq[ni * n + nj][np]) {
                    inq[ni * n + nj][np] = true;
                    dq.push([ni, nj, np]);
                }
            }
        };
        relax(i, j, d + penalty[i][j]);
        const dirs = p === 1 ? [[0,1],[1,0]] : [[0,-1],[-1,0]];
        for (const [di, dj] of dirs) {
            const ni = i + di, nj = j + dj;
            if (ni < 0 || ni >= m || nj < 0 || nj >= n) continue;
            relax(ni, nj, d + (ni + 1) * (nj + 1) + (p === 1 ? 0 : penalty[i][j]));
        }
    }
    const t = (m - 1) * n + (n - 1);
    return Math.min(dist[t][0], dist[t][1]);
};
